weekly-contest-352-sum-of-imbalance-numb:
{
  "problem_id": "sumImbalanceNumbers",
  "functions": [{
    "name": "sumImbalanceNumbers",
    "parameters": ["nums"],
    "entry_node": 1,
    "nodes": [
      {
        "id": 1,
        "type": "start",
        "label": "Start",
        "bbox": [0, 0, 0, 0],
        "next": 2
      },
      {
        "id": 2,
        "type": "process",
        "label": "Input data",
        "bbox": [0, 0, 0, 0],
        "action": "nums = ctx['arg0']; n = len(nums); res = 0; for i in range(n):\n    mask = 0\n    gaps = 0\n    for j in range(i, n):\n        x = nums[j]\n        if (mask >> x) & 1 == 0:\n            lower_mask = mask & ((1 << x) - 1)\n            if lower_mask != 0:\n                p = lower_mask.bit_length()\n            else:\n                p = None\n            t = mask >> x\n            if t != 0:\n                lowest = t & -t\n                k = (lowest).bit_length() - 1\n                q = x + k\n            else:\n                q = None\n            delta = 0\n            if p is not None and x - p > 1:\n                delta += 1\n            if q is not None and q - x > 1:\n                delta += 1\n            if p is not None and q is not None and q - p > 1:\n                delta -= 1\n            gaps += delta\n            mask |= 1 << x\n        res += gaps\nctx['result'] = res",
        "next": 3
      },
      {
        "id": 3,
        "type": "end",
        "label": "End",
        "bbox": [0, 0, 0, 0],
        "output": "ctx['result']"
      }
    ]
  }]
}

